// Use a trivially-copyable, equality-comparable T = int to satisfy template constraints.
workerd::SmallSet<int> s;
// Generate a small pool of candidate items. Using array form to avoid the same value in loops.
const int (*vals)[5] = FUZZ_PARAM(int[5]);
int a = (*vals)[0];
int b = (*vals)[1];
int c = (*vals)[2];
int d = (*vals)[3];
int e = (*vals)[4];

// Exercise small-storage states and duplicate handling.
bool r1 = s.add(a);  // should be true on first insertion
bool r2 = s.add(b);  // likely true unless equal to a
bool r3 = s.add(c);  // may trigger transition to vector-backed storage

// Validate idempotency: re-adding an existing element should return false.
bool r4 = s.add(a);
FUZZ_ASSERT(r1 == true, "First insertion must return true");
FUZZ_ASSERT(r4 == false, "Duplicate insertion must return false");

// Mix more operations to vary paths; duplicates should still be false, new may be true.
( void ) s.add(d );
( void ) s.add(e );
( void ) s.add(b ); // duplicate of possibly-existing b

// Sanity: all inserted-or-attempted values must report contains() consistent with add semantics.
// We can't assert contains() for potentially-colliding values beyond what we checked, but basic
// consistency check for 'a'.
FUZZ_ASSERT(s.contains(a), "Set must contain 'a' after successful insertion");

workerd::SmallSet<int> s;
const int (*vals)[5] = FUZZ_PARAM(int[5]);
int a = (*vals)[0];
int b = (*vals)[1];
int c = (*vals)[2];
int x = (*vals)[3]; // candidate to remove (may or may not be present)

( void ) s.add(a);
( void ) s.add(b);
( void ) s.add(c);

bool wasPresent = s.contains(x);
bool removed = s.remove(x);
FUZZ_ASSERT(removed == wasPresent, "remove() must return true iff the item was present");
if (removed) {
  FUZZ_ASSERT(!s.contains(x), "Removed item must no longer be contained");
}

// Also test removing definitely present element 'a'.
bool removedA = s.remove(a);
FUZZ_ASSERT(removedA == true, "remove(existing) must succeed");
FUZZ_ASSERT(!s.contains(a), "After removal, element must be absent");

workerd::SmallSet<int> s;
const int (*vals)[5] = FUZZ_PARAM(int[5]);
int a = (*vals)[0];
int b = (*vals)[1];
int c = (*vals)[2];
int x = (*vals)[3];

// Insert up to 3 values; duplicates are benign.
( void ) s.add(a);
( void ) s.add(b);
( void ) s.add(c);

// Expected membership for x by direct equality checks against what we inserted.
bool expected = (x == a) || (x == b) || (x == c);
bool actual = s.contains(x);
FUZZ_ASSERT(actual == expected, "contains(x) must reflect membership by equality");

workerd::SmallSet<int> s;
const int (*vals)[4] = FUZZ_PARAM(int[4]);
int v0 = (*vals)[0];
int v1 = (*vals)[1];
int v2 = (*vals)[2];
int v3 = (*vals)[3];

( void ) s.add(v0);
( void ) s.add(v1);
( void ) s.add(v2);
( void ) s.add(v3);

// Compute unique count among the four by brute force.
int uniqueCount = 0;
int items[4] = { v0, v1, v2, v3 };
for (int i = 0; i < 4; ++i) {
  bool seen = false;
  for (int j = 0; j < i; ++j) { if (items[j] == items[i]) { seen = true; break; } }
  if (!seen) ++uniqueCount;
}
FUZZ_ASSERT(s.size() == (size_t)uniqueCount, "size() must equal number of unique insertions");

workerd::SmallSet<int> s;
// Initially empty
FUZZ_ASSERT(s.empty(), "New SmallSet must be empty");
// After insertion, not empty
int val = *FUZZ_PARAM(int);
( void ) s.add(val);
FUZZ_ASSERT(!s.empty(), "SmallSet must be non-empty after insertion");

workerd::SmallSet<int> s;
const int (*vals)[3] = FUZZ_PARAM(int[3]);
( void ) s.add((*vals)[0]);
( void ) s.add((*vals)[1]);
( void ) s.add((*vals)[2]);

// Clear should drop all items and reset to empty state.
s.clear();
FUZZ_ASSERT(s.size() == 0, "clear() must reset size to 0");
FUZZ_ASSERT(s.empty(), "clear() must produce an empty set");

workerd::SmallSet<int> s;
const int (*vals)[4] = FUZZ_PARAM(int[4]);
( void ) s.add((*vals)[0]);
( void ) s.add((*vals)[1]);
( void ) s.add((*vals)[2]);
( void ) s.add((*vals)[3]);

kj::Vector<int> snap = s.snapshot();
FUZZ_ASSERT(snap.size() == s.size(), "snapshot size must equal current set size at the time of snapshot");

// Mutate the set after snapshot; the snapshot must remain unchanged in size.
( void ) s.remove((*vals)[0]);
FUZZ_ASSERT(snap.size() >= 0, "snapshot must remain valid after mutations to the set");  // basic sanity
FUZZ_ASSERT(snap.size() != (size_t)-1, "snapshot size must be a valid non-negative size_t");

workerd::SmallSet<int> s;
const int (*vals)[2] = FUZZ_PARAM(int[2]);
( void ) s.add((*vals)[0]);
( void ) s.add((*vals)[1]);

auto it = s.begin();
auto ed = s.end();

// Precondition: iterator must not be at end when dereferenced.
if (it == ed) { FUZZ_BAIL(); }

int v = *it;  // operator* under test
FUZZ_ASSERT(s.contains(v), "Dereferenced iterator value must be contained in the set");

workerd::SmallSet<int> s;
const int (*vals)[3] = FUZZ_PARAM(int[3]);
( void ) s.add((*vals)[0]);
( void ) s.add((*vals)[1]);
( void ) s.add((*vals)[2]);

auto it = s.begin();
auto ed = s.end();

// If empty, bail to avoid invalid deref; otherwise advance iterators safely.
if (it == ed) { FUZZ_BAIL(); }

// Pre-increment
++it;  // operator++() pre-increment

// Post-increment (returns previous iterator by value). Use a temporary to invoke overload.
if (it != ed) {
  auto prev = it++;
  // prev should not be equal to it after post-increment unless we were at end-1.
  // No hard assertion here to avoid depending on exact size; just ensure both are valid comparisons.
  (void)prev;
}

// Ensure we did not invalidate by mutation (we did not mutate the set here).
( void ) (it == ed);

workerd::SmallSet<int> s;
const int (*vals)[2] = FUZZ_PARAM(int[2]);
( void ) s.add((*vals)[0]);
( void ) s.add((*vals)[1]);

auto it1 = s.begin();
auto it2 = s.begin();
auto ed  = s.end();

FUZZ_ASSERT(it1 == it2, "Two begin() iterators over the same container must be equal");
if (it1 != ed) {
  ++it1;
  FUZZ_ASSERT(!(it1 == it2), "After advancing, iterators should compare unequal unless size < 2");
}

workerd::SmallSet<int> s;
const int (*vals)[2] = FUZZ_PARAM(int[2]);
( void ) s.add((*vals)[0]);
( void ) s.add((*vals)[1]);

auto it = s.begin();
auto ed = s.end();

// Begin and end should be unequal unless the set is empty.
if (s.empty()) {
  FUZZ_ASSERT(!(it != ed), "For empty set, begin() must equal end()");
} else {
  FUZZ_ASSERT(it != ed, "For non-empty set, begin() must not equal end()");
}

workerd::SmallSet<int> s;
const int (*vals)[2] = FUZZ_PARAM(int[2]);
( void ) s.add((*vals)[0]);
( void ) s.add((*vals)[1]);

auto it = s.begin();
auto ed = s.end();

// ed should act as a sentinel; advancing until ed should eventually reach equality.
// We avoid dereferencing ed.
int steps = 0;
while (it != ed && steps < 4) { ++it; ++steps; }
FUZZ_ASSERT(it == ed, "Iteration should reach end() sentinel in finite steps");

// Use a trivially-copyable, equality-comparable T = int to satisfy template constraints.
workerd::SmallSet<int> s;

// Randomly decide whether to insert one element to test both empty and non-empty states.
const int (*vals)[1] = FUZZ_PARAM(int[1]);
unsigned pick = *FUZZ_PARAM(unsigned int);
if ((pick & 1u) != 0u) {
  (void)s.add((*vals)[0]);
}

// Target under test: begin()
auto it = s.begin();
auto ed = s.end();

// Validate begin()/end() relationship based on emptiness.
if (s.empty()) {
  FUZZ_ASSERT(it == ed, "begin() must equal end() for empty set");
} else {
  FUZZ_ASSERT(it != ed, "begin() must not equal end() for non-empty set");
}

